"""Generated by the NL to Flow Diagram Encoder Pipeline."""

def COUNT_VOWELS(text):
    vowels = ['a', 'e', 'i', 'o', 'u']
    counts = []
    for v in vowels:
        count = 0
        for c in text:
            if (c == v):
                count = (count + 1)
        counts.append(count)
    return counts
